'@
$cleanBase64 = ($Base64 -replace '\s', '')
$zipPath = Join-Path ([System.IO.Path]::GetTempPath()) ('cdt-workflow-restore-' + [guid]::NewGuid().ToString('N') + '.zip')
[System.IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($cleanBase64))
$ActualSha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $zipPath).Hash.ToLowerInvariant()
if ($ActualSha256 -ne $ExpectedSha256) {
    Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
    throw "Checksum mismatch. Expected $ExpectedSha256 but got $ActualSha256."
}
if (Test-Path -LiteralPath $Destination) {
    if (-not $Force) { throw "Destination already exists: $Destination. Pass -Force to overwrite." }
    Remove-Item -LiteralPath $Destination -Recurse -Force
}
New-Item -ItemType Directory -Path $Destination | Out-Null
Expand-Archive -LiteralPath $zipPath -DestinationPath $Destination -Force
Remove-Item -LiteralPath $zipPath -Force
$RestoredFileCount = @(Get-ChildItem -LiteralPath $Destination -Recurse -File -Force).Count
if ($RestoredFileCount -ne $ExpectedFileCount) {
    throw "File count mismatch after restore. Expected $ExpectedFileCount but found $RestoredFileCount."
}
Write-Host "Checksum verified: $ActualSha256"
Write-Host "Files restored: $RestoredFileCount"
Write-Host "Restored to: $Destination"
